  --radius-xl: 16px;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

:root {
  --background: #fbfcfe;
  --foreground: #252b3a;
  --card: #ffffff;
  --primary: #6262cf;
  --radius: 0.75rem;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply m-0 bg-background font-sans text-foreground;
    font-size: 14px;
  }
  button,
  [role="button"] {
    cursor: pointer;
  }
  button:disabled {
    cursor: not-allowed;
  }
  ::selection {
    background: #e3e3fa;
  }
  :focus-visible {
    outline: 2px solid #7775dd;
    outline-offset: 3px;
  }
  input,
  textarea {
    font: inherit;
  }
}

.workspace-app {
  min-height: 100vh;
}
.workspace-sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  z-index: 35;
  display: flex;
  flex-direction: column;
  width: 236px;
  padding: 27px 17px 0;
  background: #f7f8fb;

